  computed: {
    computedDateDisplay() {
      return this.displayFormatDate(this.computedDateFormatted);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    activeFiltersCount() {
      let count = 0;

      // Count date filter (if not default)
      if (this.computedDateFormatted && this.computedDateFormatted !== this.formatDate(new Date())) {
        count++;
      }

      // Count location filter
      if (this.loaction && this.loaction !== "ALL") {
        count++;
      }

      // Count user search
      if (this.userselect && this.userselect !== "") {
        count++;
      }
      return count;
    },
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.paginatedItems;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.paginatedItems.filter(item => item.user_name && item.user_name.toLowerCase().includes(searchTerm) || item.member_id && item.member_id.toLowerCase().includes(searchTerm) || item.last_swiped_location && item.last_swiped_location.toLowerCase().includes(searchTerm) || item.total_swipes && item.total_swipes.toString().includes(searchTerm));
    },
    sortedAndPaginatedItems() {
      // First sort the filtered items
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });
      return sortedItems;
    }
  },
