    getSortValue(value, key) {
      if (!value) return "";
      if (key === "user_name" || key === "member_id" || key === "last_swiped_location") {
        return value.toLowerCase();
      }
      if (key === "total_duration" || key === "total_swipes") {
        return parseFloat(value) || 0;
      }
      if (key === "first_swipe") {
        return new Date(value).getTime();
      }
      return value;
